//! The commands the UI calls, with TypeScript bindings generated by
//! tauri-specta into `src/bindings.ts`.
//!
//! Thin wrappers over `dictation_pipeline::config::Config`. The API key is
//! write-only: `set_api_key` stores it and `has_api_key` says whether one is
//! stored; no command returns it (M3.3 criterion 2, checked against the
//! generated bindings by `tests::criterion_2_*`). Keychain calls can block
//! (and on macOS, show an access prompt), so every command runs on the
//! blocking pool, never the main thread.
//!
//! `save_settings` and `set_api_key` also rebuild the speech-to-text engine
//! from what was saved (M4.4, [`crate::engine`]), so the next dictation uses
//! the new provider, model, language or key without a restart.
//!
//! `test_api_key` (M3.4) is the one command that sends a key anywhere but
//! the keychain: to the provider, in the `Authorization` header, with a short
//! silent clip. It returns nothing but success or a [`KeyTestError`] whose
//! message is written here and never holds a key.

use std::sync::Arc;

use dictation_core::settings::{Provider, Settings};
use dictation_pipeline::config::{self, Config, ConfigError};
use dictation_pipeline::launch::{self, LaunchProblem};
use dictation_platform::secrets::KeychainSecretStore;
use dictation_ports::{LaunchAtLogin, SecretStore, TranscribeError};
use dictation_transcribe::check_key::check_key;
use dictation_transcribe::openai_compat::{self, Preset};
use serde::Serialize;
use tauri::State;

use crate::engine::{self, LiveEngine};

/// Where the bindings go, relative to `src-tauri/`.
pub const BINDINGS_PATH: &str = "../src/bindings.ts";

/// The settings file and keys the commands use.
pub struct AppConfig(pub Arc<Config<KeychainSecretStore>>);

/// The OS's login item for the launch-at-login setting (M5.3).
pub struct LoginItem(pub Arc<dyn LaunchAtLogin>);

/// Runs `call` on the config on the blocking pool; errors become the
/// message the UI shows (never a key).
async fn on_config<T: Send + 'static>(
    state: &State<'_, AppConfig>,
    call: impl FnOnce(&Arc<Config<KeychainSecretStore>>) -> Result<T, ConfigError> + Send + 'static,
) -> Result<T, String> {
    let config = Arc::clone(&state.0);
    tauri::async_runtime::spawn_blocking(move || call(&config))
        .await
        .map_err(|_| "the settings task crashed".to_owned())?
        .map_err(|error| {
            tracing::warn!(%error, "settings command failed");
            error.to_string()
        })
}

/// The saved settings (the defaults if none were saved), with
/// `launch_at_login` as the OS reports it: the user may have changed the
/// login item in System Settings since the last save.
#[tauri::command]
#[specta::specta]
pub async fn get_settings(
    state: State<'_, AppConfig>,
    login: State<'_, LoginItem>,
) -> Result<Settings, String> {
    let login = Arc::clone(&login.0);
    on_config(&state, move |config| {
        Ok(launch::with_os_state(&*login, config.settings()?))
    })
    .await
}

/// Saves the settings: the login item first, then the file with whatever the
/// OS ended up with, then the engine is rebuilt.
///
/// If the login item couldn't be changed, everything else is still saved and
/// the error says why (and what to do, if the user has to approve it).
fn save_with_login<S: SecretStore + 'static>(
    config: &Arc<Config<S>>,
    live: &LiveEngine,
    login: &dyn LaunchAtLogin,
    mut settings: Settings,
) -> Result<Option<LaunchProblem>, ConfigError> {
    let problem = launch::apply(login, &mut settings).err();
    engine::changed(config, live, |config| config.save_settings(&settings))?;
    Ok(problem)
}

/// Validates and saves the settings, and applies the launch-at-login choice
/// to the OS.
#[tauri::command]
#[specta::specta]
pub async fn save_settings(
    state: State<'_, AppConfig>,
    engine: State<'_, LiveEngine>,
    login: State<'_, LoginItem>,
    settings: Settings,
) -> Result<(), String> {
    let live = engine.inner().clone();
    let login = Arc::clone(&login.0);
    let problem = on_config(&state, move |config| {
        save_with_login(config, &live, &*login, settings)
    })
    .await?;
    problem.map_or(Ok(()), |problem| Err(problem.to_string()))
}

/// Stores `key` as `provider`'s API key in the keychain. Write-only.
#[tauri::command]
#[specta::specta]
pub async fn set_api_key(
    state: State<'_, AppConfig>,
    engine: State<'_, LiveEngine>,
    provider: Provider,
    key: String,
) -> Result<(), String> {
    let live = engine.inner().clone();
    on_config(&state, move |config| {
        engine::changed(config, &live, |config| config.set_api_key(provider, &key))
    })
    .await
}

/// Whether `provider` has an API key stored.
#[tauri::command]
#[specta::specta]
pub async fn has_api_key(state: State<'_, AppConfig>, provider: Provider) -> Result<bool, String> {
    on_config(&state, move |config| config.has_api_key(provider)).await
}

/// What went wrong when testing a key, so the UI can pick its wording.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, specta::Type)]
#[serde(rename_all = "snake_case")]
pub enum KeyTestKind {
    /// No key was typed or saved to test.
    NoKey,
    /// The key can't be a key, or the provider rejected it.
    InvalidKey,
    /// The provider is rate limiting; the key may be fine.
    RateLimited,
    /// The provider couldn't be reached (offline, DNS, timeout).
    Network,
    /// The provider failed or gave an answer we can't use.
    Server,
    /// The saved key couldn't be read from the keychain.
    Keychain,
}

/// Why a key test failed. Never contains the key.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, specta::Type)]
pub struct KeyTestError {
    /// The category.
    pub kind: KeyTestKind,
    /// What to show the user.
    pub message: String,
}

impl KeyTestError {
    fn new(kind: KeyTestKind, message: impl Into<String>) -> Self {
        Self {
            kind,
            message: message.into(),
        }
    }
}

/// The provider's name for messages.
fn provider_name(provider: Provider) -> &'static str {
    match provider {
        Provider::Groq => "Groq",
        Provider::OpenAi => "OpenAI",
    }
}

/// The user-facing error for a failed check. The messages are fixed text
/// plus the engine's own detail, which never holds the key, the audio or a
/// transcript (`TranscribeError`).
fn describe(provider: Provider, error: &TranscribeError) -> KeyTestError {
    let name = provider_name(provider);
    match error {
        TranscribeError::MissingKey => KeyTestError::new(
            KeyTestKind::NoKey,
            format!("No {name} API key is saved yet. Paste one first."),
        ),
        TranscribeError::InvalidKey => KeyTestError::new(
            KeyTestKind::InvalidKey,
            format!(
                "{name} rejected this API key. Check that you copied the whole key from {name}."
            ),
        ),
        TranscribeError::RateLimited => KeyTestError::new(
            KeyTestKind::RateLimited,
            format!(
                "{name} is limiting requests right now. The key may be fine; try again in a minute."
            ),
        ),
        TranscribeError::Timeout => KeyTestError::new(
            KeyTestKind::Network,
            format!("{name} didn't answer in time. Check your internet connection and try again."),
        ),
        TranscribeError::Network(_) => KeyTestError::new(
            KeyTestKind::Network,
            format!("Couldn't reach {name}. Check your internet connection and try again."),
        ),
        // The key test reads the keychain itself and reports its errors
        // (`KeyTestKind::Keychain`); these two come from the dictation engine.
        TranscribeError::KeyPending | TranscribeError::KeychainUnavailable(_) => KeyTestError::new(
            KeyTestKind::Keychain,
            "Couldn't read your API key from the Keychain.".to_owned(),
        ),
        TranscribeError::Engine(detail) => KeyTestError::new(
            KeyTestKind::Server,
            format!(
                "{name} had a problem, so the key couldn't be checked ({detail}). Try again later."
            ),
        ),
    }
}

/// Tests `typed`, or the stored key if `typed` is `None`, against
/// `provider` at `base_url`. A typed key is only used for this request;
/// it is not stored (saving it is `set_api_key`'s job).
async fn key_test<S: SecretStore + 'static>(
    config: &Arc<Config<S>>,
    provider: Provider,
    typed: Option<String>,
    base_url: &str,
) -> Result<(), KeyTestError> {
    let name = provider_name(provider);
    let (key, source) = match typed {
        Some(typed) => {
            let key = config::validate_key(&typed).map_err(|error| match error {
                ConfigError::InvalidKey(reason) => {
                    KeyTestError::new(KeyTestKind::InvalidKey, format!("The API key {reason}."))
                }
                other => KeyTestError::new(KeyTestKind::Keychain, other.to_string()),
            })?;
            (key, "typed")
        }
        None => {
            let stored = Arc::clone(config);
            let stored = tokio::task::spawn_blocking(move || stored.api_key(provider))
                .await
                .map_err(|_| KeyTestError::new(KeyTestKind::Keychain, "the keychain task crashed"))?
                .map_err(|error| {
                    KeyTestError::new(
                        KeyTestKind::Keychain,
                        format!("Couldn't read the saved key: {error}."),
                    )
                })?;
            let key = stored.ok_or_else(|| {
                KeyTestError::new(
                    KeyTestKind::NoKey,
                    format!("No {name} API key is saved yet. Paste one first."),
                )
            })?;
            (key, "stored")
        }
    };
    let engine = openai_compat::Config {
        base_url: base_url.to_owned(),
        ..openai_compat::Config::from_preset(Preset::for_provider(provider))
    };
    let result = check_key(engine, key).await;
    match &result {
        Ok(()) => tracing::info!(%provider, source, "API key works"),
        Err(error) => tracing::warn!(%provider, source, %error, "API key test failed"),
    }
    result.map_err(|error| describe(provider, &error))
}

/// Tests an API key with a short silent clip through `provider`'s
/// transcription endpoint: the key typed in the form (`key`, used for this
/// request only and not stored), or the saved one if `key` is `None`. The
/// key never comes back; the result is success or a [`KeyTestError`].
#[tauri::command]
#[specta::specta]
pub async fn test_api_key(
    state: State<'_, AppConfig>,
    provider: Provider,
    key: Option<String>,
) -> Result<(), KeyTestError> {
    key_test(
        &state.0,
        provider,
        key,
        Preset::for_provider(provider).base_url,
    )
    .await
}

/// Every command, for the invoke handler and the bindings. Generic over the
/// runtime so the ACL tests can run the real handler on Tauri's mock runtime.
pub fn builder<R: tauri::Runtime>() -> tauri_specta::Builder<R> {
    tauri_specta::Builder::<R>::new().commands(tauri_specta::collect_commands![
        get_settings,
        save_settings,
        set_api_key,
        has_api_key,
        test_api_key,
    ])
}

/// Writes the TypeScript bindings to `path`.
///
/// # Errors
///
/// If they can't be generated or written.
pub fn export_bindings(path: &std::path::Path) -> Result<(), String> {
    builder::<tauri::Wry>()
        .export(
            specta_typescript::Typescript::default()
                .header("// Generated by tauri-specta from src-tauri/src/commands.rs. Don't edit;\n// regenerate with: UPDATE_BINDINGS=1 cargo test -p dictation-app commands::\n"),
            path,
        )
        .map_err(|error| error.to_string())
}

#[cfg(test)]
mod tests {
    use std::path::PathBuf;

    use super::*;

    fn committed() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(BINDINGS_PATH)
    }

    /// Fresh bindings, as text. With `UPDATE_BINDINGS=1` they also replace
    /// the committed `src/bindings.ts`.
    fn generated() -> String {
        let path =
            std::env::temp_dir().join(format!("dictation-bindings-{}.ts", std::process::id()));
        export_bindings(&path).unwrap();
        let text = std::fs::read_to_string(&path).unwrap();
        let _ = std::fs::remove_file(&path);
        if std::env::var_os("UPDATE_BINDINGS").is_some() {
            std::fs::write(committed(), &text).unwrap();
        }
        text
    }

    #[test]
    fn the_committed_bindings_are_up_to_date() {
        let fresh = generated();
        let committed = std::fs::read_to_string(committed()).unwrap();
        assert!(
            fresh == committed,
            "src/bindings.ts is stale; regenerate with UPDATE_BINDINGS=1 cargo test -p dictation-app commands::"
        );
    }

    #[test]
    fn criterion_2_the_bindings_have_exactly_the_five_commands() {
        let bindings = std::fs::read_to_string(committed()).unwrap();
        for command in [
            "getSettings",
            "saveSettings",
            "setApiKey",
            "hasApiKey",
            "testApiKey",
        ] {
            assert!(
                bindings.contains(&format!("\t{command}: (")),
                "{command} missing"
            );
        }
        let commands = bindings.matches("__TAURI_INVOKE(\"").count();
        assert_eq!(
            commands, 5,
            "a command was added; check it doesn't return a key"
        );
    }

    #[test]
    fn the_app_requires_macos_13_for_the_login_item_api() {
        // SMAppService is macOS 13+; the adapter calls it without a check.
        let config = std::fs::read_to_string(
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tauri.conf.json"),
        )
        .unwrap();
        let config: serde_json::Value = serde_json::from_str(&config).unwrap();
        assert_eq!(
            config["bundle"]["macOS"]["minimumSystemVersion"], "13.0",
            "raise the minimum before using a newer macOS API, never lower it"
        );
    }

    #[test]
    fn the_ui_default_models_match_core() {
        let providers = std::fs::read_to_string(
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../src/providers.ts"),
        )
        .unwrap();
        for provider in Provider::ALL {
            let entry = format!(
                "id: \"{provider}\", name: \"{}\", defaultModel: \"{}\"",
                provider_name(provider),
                provider.default_model()
            );
            assert!(providers.contains(&entry), "src/providers.ts lacks {entry}");
        }
    }

    /// The field names of a generated TypeScript object type's body.
    fn field_names(body: &str) -> Vec<&str> {
        body.lines()
            .map(str::trim)
            .filter(|line| !line.starts_with('/') && !line.starts_with('*'))
            .filter_map(|line| line.split(':').next())
            .filter(|field| !field.is_empty())
            .collect()
    }

    #[test]
    fn criterion_2_no_command_returns_the_key() {
        let bindings = std::fs::read_to_string(committed()).unwrap();
        assert!(
            !bindings.to_lowercase().contains("getapikey"),
            "a key getter exists"
        );
        let command = |name: &str| {
            bindings
                .lines()
                .find(|line| line.contains(&format!("\t{name}: (")))
                .unwrap()
                .to_owned()
        };
        // The key goes in and nothing comes back; the check returns a bool.
        assert!(command("setApiKey").contains("typedError<null, string>"));
        assert!(command("hasApiKey").contains("typedError<boolean, string>"));
        // The Test key command sends the key out and returns success or a
        // `KeyTestError` (kind and message), never the key.
        assert!(command("testApiKey").contains("typedError<null, KeyTestError>"));
        let error = bindings
            .split("export type KeyTestError = {")
            .nth(1)
            .and_then(|rest| rest.split("\n};").next())
            .unwrap();
        assert_eq!(field_names(error), ["kind", "message"]);
        assert!(error.contains("kind: KeyTestKind") && error.contains("message: string"));
        // Settings, the only other type sent back, has no key field.
        let settings = bindings
            .split("export type Settings_Serialize = {")
            .nth(1)
            .and_then(|rest| rest.split("\n};").next())
            .unwrap();
        let fields = field_names(settings);
        assert_eq!(
            fields,
            [
                "version",
                "provider",
                "model",
                "language",
                "hotkey",
                "launch_at_login"
            ]
        );
    }

    mod launch_at_login {
        use dictation_platform::fakes::{FakeLaunchAtLogin, MemSecretStore};
        use dictation_ports::LaunchAtLoginState;

        use super::super::*;

        fn config() -> (Arc<Config<MemSecretStore>>, std::path::PathBuf) {
            let dir = std::env::temp_dir().join(format!(
                "dictation-login-test-{}-{:?}",
                std::process::id(),
                std::thread::current().id()
            ));
            (Arc::new(Config::new(&dir, MemSecretStore::new())), dir)
        }

        fn on() -> Settings {
            Settings {
                launch_at_login: true,
                ..Settings::default()
            }
        }

        #[test]
        fn saving_applies_the_choice_to_the_os_and_the_file_keeps_the_result() {
            let (config, dir) = config();
            let login = FakeLaunchAtLogin::new();
            let live = LiveEngine::fixed();
            let problem = save_with_login(&config, &live, &login, on()).unwrap();
            assert_eq!(problem, None);
            assert_eq!(login.state(), Ok(LaunchAtLoginState::Enabled));
            assert!(config.settings().unwrap().launch_at_login);

            // The user turns it off in System Settings; the screen shows
            // that, and saving something else doesn't turn it back on.
            login.set_state(LaunchAtLoginState::Disabled);
            let shown = launch::with_os_state(&login, config.settings().unwrap());
            assert!(!shown.launch_at_login);
            assert_eq!(
                save_with_login(&config, &live, &login, shown).unwrap(),
                None
            );
            assert!(!config.settings().unwrap().launch_at_login);
            assert_eq!(login.calls(), [true]);
            let _ = std::fs::remove_dir_all(dir);
        }

        #[test]
        fn a_refused_login_item_still_saves_the_other_settings() {
            let (config, dir) = config();
            let login = FakeLaunchAtLogin::new();
            login.enabling_gives(LaunchAtLoginState::RequiresApproval);
            let settings = Settings {
                language: Some("de".into()),
                ..on()
            };
            let problem = save_with_login(&config, &LiveEngine::fixed(), &login, settings).unwrap();
            assert_eq!(problem, Some(LaunchProblem::NeedsApproval));
            let saved = config.settings().unwrap();
            assert_eq!(saved.language.as_deref(), Some("de"));
            assert!(!saved.launch_at_login, "not claimed as on");
            let _ = std::fs::remove_dir_all(dir);
        }

        #[test]
        fn invalid_settings_are_not_saved() {
            let (config, dir) = config();
            let login = FakeLaunchAtLogin::new();
            let bad = Settings {
                model: String::new(),
                ..on()
            };
            assert!(save_with_login(&config, &LiveEngine::fixed(), &login, bad).is_err());
            let _ = std::fs::remove_dir_all(dir);
        }
    }

    mod key_test {
        use dictation_pipeline::config::Config;
        use dictation_platform::fakes::MemSecretStore;
        use wiremock::matchers::{header, method, path};
        use wiremock::{Mock, MockServer, ResponseTemplate};

        use super::super::*;

        /// Obviously fake; every test checks it never appears in an error.
        const STORED: &str = "stored-key-NOT-REAL-5d41402a";
        const TYPED: &str = "typed-key-NOT-REAL-7b3d9e1f";

        fn config(dir: &std::path::Path) -> (Arc<Config<MemSecretStore>>, MemSecretStore) {
            let secrets = MemSecretStore::new();
            (Arc::new(Config::new(dir, secrets.clone())), secrets)
        }

        fn temp() -> std::path::PathBuf {
            std::env::temp_dir().join("dictation-key-test-unused")
        }

        async fn provider(status: u16, key: &str) -> MockServer {
            let server = MockServer::start().await;
            Mock::given(method("POST"))
                .and(path("/audio/transcriptions"))
                .and(header("authorization", format!("Bearer {key}").as_str()))
                .respond_with(ResponseTemplate::new(status).set_body_string(r#"{"text":""}"#))
                .mount(&server)
                .await;
            server
        }

        async fn run(
            typed: Option<&str>,
            secrets: Option<&str>,
            server: &MockServer,
        ) -> (Result<(), KeyTestError>, MemSecretStore) {
            let (config, store) = config(&temp());
            if let Some(key) = secrets {
                config.set_api_key(Provider::Groq, key).unwrap();
            }
            let result = key_test(
                &config,
                Provider::Groq,
                typed.map(str::to_owned),
                &server.uri(),
            )
            .await;
            (result, store)
        }

        #[tokio::test]
        async fn the_stored_key_is_used_when_none_is_typed() {
            let server = provider(200, STORED).await;
            let (result, _) = run(None, Some(STORED), &server).await;
            assert_eq!(result, Ok(()));
        }

        #[tokio::test]
        async fn a_typed_key_is_used_and_not_stored() {
            let server = provider(200, TYPED).await;
            // A different key is stored; the typed one wins.
            let (result, store) = run(Some(&format!("  {TYPED}\n")), Some(STORED), &server).await;
            assert_eq!(result, Ok(()));
            assert_eq!(
                store.get("groq-api-key").unwrap().unwrap().expose(),
                STORED,
                "testing doesn't overwrite the saved key"
            );
            // Nothing stored beforehand: still nothing afterwards.
            let (result, store) = run(Some(TYPED), None, &server).await;
            assert_eq!(result, Ok(()));
            assert_eq!(store.get("groq-api-key").unwrap(), None);
        }

        #[tokio::test]
        async fn each_failure_has_a_kind_and_a_readable_message_without_the_key() {
            for (status, kind, words) in [
                (401, KeyTestKind::InvalidKey, "rejected this API key"),
                (403, KeyTestKind::InvalidKey, "rejected this API key"),
                (429, KeyTestKind::RateLimited, "limiting requests"),
                (503, KeyTestKind::Server, "HTTP 503"),
                (400, KeyTestKind::Server, "HTTP 400"),
            ] {
                let server = provider(status, TYPED).await;
                let (result, _) = run(Some(TYPED), None, &server).await;
                let error = result.unwrap_err();
                assert_eq!(error.kind, kind, "HTTP {status}");
                assert!(error.message.contains(words), "{}", error.message);
                assert!(error.message.contains("Groq"), "{}", error.message);
                assert!(!error.message.contains(TYPED));
            }
        }

        #[tokio::test]
        async fn an_unreachable_provider_is_a_network_error() {
            let port = std::net::TcpListener::bind("127.0.0.1:0")
                .unwrap()
                .local_addr()
                .unwrap()
                .port();
            let (config, _) = config(&temp());
            let error = key_test(
                &config,
                Provider::Groq,
                Some(TYPED.to_owned()),
                &format!("http://127.0.0.1:{port}"),
            )
            .await
            .unwrap_err();
            assert_eq!(error.kind, KeyTestKind::Network);
            assert!(
                error.message.contains("Couldn't reach Groq"),
                "{}",
                error.message
            );
            assert!(!error.message.contains(TYPED));
        }

        #[tokio::test]
        async fn without_a_stored_or_typed_key_there_is_nothing_to_test() {
            let server = provider(200, STORED).await;
            let (result, _) = run(None, None, &server).await;
            let error = result.unwrap_err();
            assert_eq!(error.kind, KeyTestKind::NoKey);
            assert!(
                error.message.contains("No Groq API key"),
                "{}",
                error.message
            );
            assert!(
                server.received_requests().await.unwrap().is_empty(),
                "no request without a key"
            );
        }

        #[tokio::test]
        async fn a_typed_key_that_cant_be_a_key_is_refused_before_any_request() {
            let server = provider(200, STORED).await;
            for (typed, why) in [
                ("", "is empty"),
                ("   ", "is empty"),
                ("two words", "contains spaces"),
            ] {
                let (result, _) = run(Some(typed), Some(STORED), &server).await;
                let error = result.unwrap_err();
                assert_eq!(error.kind, KeyTestKind::InvalidKey);
                assert_eq!(error.message, format!("The API key {why}."));
            }
            assert!(server.received_requests().await.unwrap().is_empty());
        }

        #[tokio::test]
        async fn a_denied_keychain_is_reported_as_such() {
            let server = provider(200, STORED).await;
            let (config, secrets) = config(&temp());
            secrets.set_access_denied(true);
            let error = key_test(&config, Provider::Groq, None, &server.uri())
                .await
                .unwrap_err();
            assert_eq!(error.kind, KeyTestKind::Keychain);
            assert!(error.message.contains("keychain access was denied"));
        }

        #[tokio::test]
        async fn openai_errors_name_openai() {
            let (config, _) = config(&temp());
            let server = provider(401, TYPED).await;
            let error = key_test(
                &config,
                Provider::OpenAi,
                Some(TYPED.to_owned()),
                &server.uri(),
            )
            .await
            .unwrap_err();
            assert!(
                error.message.contains("OpenAI rejected"),
                "{}",
                error.message
            );
        }

        #[test]
        fn each_provider_tests_against_its_own_base_url() {
            assert_eq!(
                Preset::for_provider(Provider::Groq).base_url,
                "https://api.groq.com/openai/v1"
            );
            assert_eq!(
                Preset::for_provider(Provider::OpenAi).base_url,
                "https://api.openai.com/v1"
            );
        }
    }
}

/// The capabilities the UI gets (M1.7, #82 M1; M5.1 B1), checked with
/// Tauri's own ACL resolver against the manifests and capabilities the
/// build script produced for this build, and by invoking the real commands
/// on Tauri's mock runtime with that ACL.
#[cfg(test)]
mod capability_tests {
    use std::collections::BTreeMap;
    use std::path::PathBuf;

    use tauri::ipc::{CallbackFn, InvokeBody, RuntimeAuthority};
    use tauri::test::{
        INVOKE_KEY, MockRuntime, get_ipc_response, mock_builder, mock_context, noop_assets,
    };
    use tauri::webview::InvokeRequest;
    use tauri::{App, Manager as _, WebviewWindow, WebviewWindowBuilder};
    use tauri_utils::acl::capability::Capability;
    use tauri_utils::acl::manifest::Manifest;
    use tauri_utils::acl::resolved::Resolved;
    use tauri_utils::platform::Target;

    use super::AppConfig;
    use crate::command_names::COMMAND_NAMES;
    use crate::engine::LiveEngine;

    /// The settings window: the app's commands.
    const MAIN: &str = "main";
    /// The overlay window (M5.1): listening to events and nothing else.
    const OVERLAY: &str = "overlay";
    const OVERLAY_COMMANDS: [&str; 2] = ["plugin:event|listen", "plugin:event|unlisten"];

    fn manifests() -> BTreeMap<String, Manifest> {
        let path = PathBuf::from(env!("OUT_DIR")).join("acl-manifests.json");
        serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
    }

    fn resolved() -> Resolved {
        let path = PathBuf::from(env!("OUT_DIR")).join("capabilities.json");
        let capabilities: BTreeMap<String, Capability> =
            serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
        Resolved::resolve(&manifests(), capabilities, Target::current()).unwrap()
    }

    /// The windows each allowed command is allowed in.
    fn allowed_windows() -> BTreeMap<String, Vec<String>> {
        resolved()
            .allowed_commands
            .into_iter()
            .map(|(name, commands)| {
                let mut windows = Vec::new();
                for command in commands {
                    assert!(command.webviews.is_empty(), "{name}: by webview");
                    windows.extend(command.windows.iter().map(|w| w.as_str().to_owned()));
                }
                (name, windows)
            })
            .collect()
    }

    #[test]
    fn criterion_m1_7_2_main_may_call_only_the_app_commands() {
        let mut expected: BTreeMap<String, Vec<String>> = COMMAND_NAMES
            .iter()
            .map(|name| ((*name).to_owned(), vec![MAIN.to_owned()]))
            .collect();
        // M5.1 B1: the overlay listens to its event, nothing more, and no
        // app command reaches it.
        for command in OVERLAY_COMMANDS {
            expected.insert(command.to_owned(), vec![OVERLAY.to_owned()]);
        }
        assert_eq!(
            allowed_windows(),
            expected,
            "nothing else from core: or any plugin"
        );
    }

    #[test]
    fn criterion_m1_7_2_the_tray_and_menus_are_out_of_reach() {
        let allowed = resolved().allowed_commands;
        for command in [
            "plugin:tray|get_by_id",
            "plugin:tray|remove_by_id",
            "plugin:tray|set_visible",
            "plugin:tray|set_menu",
            "plugin:menu|set_enabled",
            "plugin:resources|close",
            "plugin:window|hide",
            "plugin:event|emit",
            "plugin:event|emit_to",
        ] {
            assert!(!allowed.contains_key(command), "{command} is allowed");
        }
    }

    fn capability_file(name: &str) -> serde_json::Value {
        let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("capabilities")
            .join(name);
        serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
    }

    #[test]
    fn criterion_m1_7_2_the_capability_files_list_exactly_the_commands() {
        let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("capabilities");
        let mut files: Vec<_> = std::fs::read_dir(&dir)
            .unwrap()
            .map(|entry| entry.unwrap().file_name())
            .collect();
        files.sort();
        assert_eq!(
            files,
            ["default.json", "overlay.json"],
            "two capability files"
        );

        let main = capability_file("default.json");
        let expected: Vec<String> = COMMAND_NAMES
            .iter()
            .map(|name| format!("allow-{}", name.replace('_', "-")))
            .collect();
        assert_eq!(main["permissions"], serde_json::json!(expected));
        assert_eq!(main["windows"], serde_json::json!([MAIN]));
        assert!(main.get("webviews").is_none());
        assert!(main.get("remote").is_none());

        let overlay = capability_file("overlay.json");
        assert_eq!(
            overlay["permissions"],
            serde_json::json!(["core:event:allow-listen", "core:event:allow-unlisten"])
        );
        assert_eq!(overlay["windows"], serde_json::json!([OVERLAY]));
        assert!(overlay.get("webviews").is_none());
        assert!(overlay.get("remote").is_none());
    }

    /// The app on Tauri's mock runtime with this build's ACL and the real
    /// command handler, its settings in a fresh directory (no keychain call
    /// is made by the commands invoked below), and a window per label.
    fn app_with_windows(labels: &[&str]) -> (App<MockRuntime>, Vec<WebviewWindow<MockRuntime>>) {
        let manifests = manifests();
        let resolved = resolved();
        assert!(resolved.has_app_acl, "build.rs declares the app manifest");
        let mut context = mock_context(noop_assets());
        *context.runtime_authority_mut() = RuntimeAuthority::new(manifests, resolved);
        let app = mock_builder()
            .invoke_handler(super::builder::<MockRuntime>().invoke_handler())
            .build(context)
            .unwrap();
        let dir = std::env::temp_dir().join(format!(
            "dictation-acl-{}-{}",
            std::process::id(),
            labels.join("-")
        ));
        app.manage(AppConfig(std::sync::Arc::new(
            dictation_pipeline::config::Config::new(
                &dir,
                dictation_platform::secrets::KeychainSecretStore::new(),
            ),
        )));
        app.manage(crate::commands::LoginItem(std::sync::Arc::new(
            dictation_platform::fakes::FakeLaunchAtLogin::new(),
        )));
        app.manage(LiveEngine::fixed());
        let windows = labels
            .iter()
            .map(|label| {
                WebviewWindowBuilder::new(&app, *label, tauri::WebviewUrl::default())
                    .build()
                    .unwrap()
            })
            .collect();
        (app, windows)
    }

    fn invoke(
        window: &WebviewWindow<MockRuntime>,
        command: &str,
        args: serde_json::Value,
    ) -> Result<tauri::ipc::InvokeResponseBody, serde_json::Value> {
        get_ipc_response(
            window,
            InvokeRequest {
                cmd: command.into(),
                callback: CallbackFn(0),
                error: CallbackFn(1),
                url: "tauri://localhost".parse().unwrap(),
                body: InvokeBody::Json(args),
                headers: tauri::http::HeaderMap::default(),
                invoke_key: INVOKE_KEY.into(),
            },
        )
    }

    /// Valid arguments for each command, so a refusal can only be the ACL's.
    fn args(command: &str) -> serde_json::Value {
        match command {
            "save_settings" => {
                serde_json::json!({ "settings": dictation_core::settings::Settings::default() })
            }
            "set_api_key" => serde_json::json!({ "provider": "groq", "key": "gsk_not_a_real_key" }),
            "has_api_key" | "test_api_key" => serde_json::json!({ "provider": "groq" }),
            _ => serde_json::json!({}),
        }
    }

    /// M5.1 B1: the overlay can't call any app command, though it's a local
    /// window of this app; the ACL refuses before the command runs.
    #[test]
    fn criterion_m5_1_2_the_overlay_may_not_invoke_any_app_command() {
        let (_app, windows) = app_with_windows(&[OVERLAY]);
        for command in COMMAND_NAMES {
            let error = invoke(&windows[0], command, args(command)).unwrap_err();
            let message = error.to_string();
            assert!(message.contains("not allowed"), "{command}: {message}");
        }
    }

    /// ...while the settings window still can (`get_settings` and
    /// `save_settings` touch only the settings file, not the keychain).
    #[test]
    fn criterion_m5_1_2_the_settings_window_may_invoke_the_app_commands() {
        let (_app, windows) = app_with_windows(&[MAIN, OVERLAY]);
        let main = &windows[0];
        invoke(main, "get_settings", args("get_settings")).unwrap();
        invoke(main, "save_settings", args("save_settings")).unwrap();
        // And the overlay, beside it, still can't.
        assert!(invoke(&windows[1], "save_settings", args("save_settings")).is_err());
    }

    #[test]
    fn the_command_names_are_the_registered_commands() {
        let bindings = std::fs::read_to_string(
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(super::BINDINGS_PATH),
        )
        .unwrap();
        let invoked: Vec<&str> = bindings
            .split("__TAURI_INVOKE(\"")
            .skip(1)
            .filter_map(|rest| rest.split_once('"').map(|(name, _)| name))
            .collect();
        assert_eq!(invoked, COMMAND_NAMES);
    }
}
